from pathlib import Path
import json, html
p=Path(__file__).parent
d=json.loads((p/'dist/data.json').read_text())
base='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f4ef"><meta name="description" content="Атлас предприятий Молдовы: направления, источники, контакты и вопросы для поиска потребителей электроэнергии от 30 000 MDL в месяц."><title>{title} · Energy MD</title><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">К содержимому</a><header class="site-header"><a class="brand" href="/" aria-label="Energy MD — главная"><span class="brand-mark">E<span>↗</span></span><span>ENERGY<span class="brand-md">MD</span><small>АТЛАС КОМПАНИЙ</small></span></a><nav aria-label="Главная навигация"><a href="/catalog/">Компании</a><a href="/sectors/">Направления</a><a href="/wave/">Дневной приоритет</a><a href="/registry/">Реестр ASP</a><a href="/research/">Поиск и вопросы</a><a href="/method/">Методика</a></nav><a class="header-link" href="/sources/" aria-label="Источники и документы">Документы <span>↗</span></a></header><main id="main"><div class="loading">Загружаем атлас компаний…</div></main><footer><a class="brand footer-brand" href="/">ENERGY MD <span>↗</span></a><p>Предприятия и организации Республики Молдова.<br>Проверка 17.10.2026 · ASP и CNED.</p><a href="/sources/">Источники ↗</a><a href="/public-energy/">Потребление CNED ↗</a><span class="footer-note">Кандидаты для проверки.<br>Потребление не подтверждено счетами.</span></footer><div id="toast" role="status" aria-live="polite"></div></body></html>'''
routes={'':'Энергия для роста','catalog':'Каталог компаний','sectors':str(len(d['sectors']))+' направлений','registry':'Расширенный реестр ASP','public-energy':'Потребление CNED','wave':'Дневной приоритет','research':'Поиск и вопросы','method':'Методика отбора','sources':'Источники и документы'}
routes.update({'company/'+c['id']:c['name'] for c in d['companies']})
routes.update({'sector/'+s['id']:s['name'] for s in d['sectors']})
for route,title in routes.items():
 out=p/'dist'/route/'index.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(base.replace('{title}',html.escape(title)))
(p/'dist/404.html').write_text(base.replace('{title}','Страница не найдена'))
print(f'Created {len(routes)} pages')
